update_rule.pseudocode:
if network_type == 'small_world':
    G = watts_strogatz_graph(n=population_size, k=average_degree, p=small_world_rewiring_prob, seed=seed)
elif network_type == 'erdos_renyi':
    p = average_degree/(population_size-1)
    G = erdos_renyi_graph(n=population_size, p=p, seed=seed)
elif network_type == 'scale_free':
    m = max(1, average_degree//2)
    G = barabasi_albert_graph(n=population_size, m=m, seed=seed)
assign neighbors to each Person.network_neighbors from G
outputs.graph.social_network = G

// Allocate time across locations: home 12h, work 8h (if employed), public 4h
for each Person i:
    contacts = []
    observed_masked = 0
    total_contacts = 0
    // home
    ch = round(base_contact_rate_per_person * contact_rate_multiplier_home)
    for k in 1..ch:
        j = random_household_member(i)
        contacts.append(j)
    // work
    cw = round(base_contact_rate_per_person * contact_rate_multiplier_work)
    for k in 1..cw:
        j = random_work_contact(i)
        contacts.append(j)
    // public
    cp = round(base_contact_rate_per_person * contact_rate_multiplier_public)
    for k in 1..cp:
        j = random_public_contact(i)
        contacts.append(j)
    for j in contacts:
        total_contacts += 1
        if Person[j].mask_usage_state == 1: observed_masked += 1
        // enforcement when mandate active and i unmasked in work/public
        if policy.mandate_active and Person[i].mask_usage_state == 0 and Bernoulli(policy.enforcement_strength * 0.5):
            Person[i].compliance_propensity = clip(Person[i].compliance_propensity + 0.05, 0, 1)
            enforcement_events += 1
    obs_mask_fraction[i] = (observed_masked / max(1, total_contacts))
outputs.observation.mask_fraction_seen = obs_mask_fraction
outputs.events.enforcement_count = enforcement_events

for each Person i:
    // Update perceived risk from environment and observations
    env_term = perceived_risk_sensitivity_to_prevalence * signal.prevalence
    obs_term = 0.5 * (1 - observation.mask_fraction_seen[i])
    info_term = 0.2 * policy.campaign_intensity * Person[i].trust_in_authorities
    Person[i].perceived_risk = clip(risk_perception_weight * (env_term + obs_term + info_term), 0, 1)
    // Social influence (DeGroot) blending neighbors' attitudes
    neigh_att = mean(Person[j].mask_attitude for j in Person[i].network_neighbors)
    lambda_i = clip(social_influence_strength * Person[i].social_influence_susceptibility, 0, 1)
    Person[i].mask_attitude = clip((1 - lambda_i) * Person[i].mask_attitude + lambda_i * neigh_att, -1, 1)
    // Intention score and compliance probability
    S = 2.0*Person[i].perceived_risk + 1.5*Person[i].mask_attitude + (policy.mandate_active ? (policy.enforcement_strength + Person[i].trust_in_authorities) : 0) - 1.0*Person[i].fatigue_level - 0.3*(mask_price / max(1, Person[i].income/365.0))
    p_wear = sigmoid(S)
    // If mandate active, boost effective compliance
    if policy.mandate_active:
        p_wear = 1 - (1 - p_wear) * (1 - Person[i].compliance_propensity)
    // Check inventory and purchase if needed
    if Person[i].mask_inventory <= 0 and p_wear > 0.5:
        p_buy = max_daily_purchase_prob * signal.mask_availability * (Person[i].income > 0 ? 1.0 : 0.5)
        if Bernoulli(p_buy):
            Person[i].mask_inventory += purchase_pack_size
    // Decide and update mask use
    will_wear = Bernoulli(p_wear) and Person[i].mask_inventory > 0
    Person[i].mask_usage_state = 1 if will_wear else 0
    if will_wear: Person[i].mask_inventory -= 1
    // Fatigue dynamics
    if Person[i].mask_usage_state == 1:
        Person[i].fatigue_level = clip(Person[i].fatigue_level + fatigue_rate, 0, 1)
    else:
        Person[i].fatigue_level = clip(Person[i].fatigue_level - recovery_from_fatigue_rate, 0, 1)
outputs.state.person_updates = all updated fields

masked = sum(Person[i].mask_usage_state for i in Persons)
adoption_rate = masked / population_size
observable.adoption_rate_daily[t] = adoption_rate
observable.masked_count_daily[t] = masked
if policy.mandate_active:
    eligible = count(Persons in work or public contexts)
    compliant = count(Persons with mask_usage_state == 1 in those contexts)
    observable.compliance_rate_when_mandate[t] = (compliant / max(1, eligible))
else:
    observable.compliance_rate_when_mandate[t] = NaN
// group by income quintile
quintiles = compute_income_quintiles(Persons)
for q in 1..5:
    members = [i for i in Persons if income_quintile(i) == q]
    observable.adoption_by_income_quintile_daily[q][t] = mean(Person[i].mask_usage_state for i in members)
// misinformation events tracking
observable.misinformation_event_days[t] = 1 if events.misinformation else 0
// cumulative
observable.cumulative_person_days_masked[t] = (observable.cumulative_person_days_masked[t-1] if t>0 else 0) + masked
